import{_ as t,o as s,c as a,ax as n}from"./chunks/framework.Buhf-QP1.js";const k=JSON.parse('{"title":"SDK Concepts","description":"How the single sdk object passed to init(sdk) combines the widget runtime with the sdk.connectors and sdk.web namespaces, and why each is a separate layer","frontmatter":{"description":"How the single sdk object passed to init(sdk) combines the widget runtime with the sdk.connectors and sdk.web namespaces, and why each is a separate layer"},"headers":[],"relativePath":"sdk/concepts.md","filePath":"sdk/concepts.md"}'),o={name:"sdk/concepts.md"};function i(d,e,r,c,h,l){return s(),a("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/sdk/concepts.md for this page in Markdown format</div><h1 id="sdk-concepts" tabindex="-1">SDK Concepts <a class="header-anchor" href="#sdk-concepts" aria-label="Permalink to &quot;SDK Concepts&quot;">​</a></h1><p>Your widget&#39;s <code>init(sdk)</code> function receives one <code>sdk</code> object. It is the single entry point to everything the platform offers widget code. This page explains what is on that object, why it is split into separate layers, and which page to go to for each.</p><h2 id="one-sdk-object-three-layers" tabindex="-1">One <code>sdk</code> object, three layers <a class="header-anchor" href="#one-sdk-object-three-layers" aria-label="Permalink to &quot;One \`sdk\` object, three layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>What it is</th><th>How you access it</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><strong><a href="/docs/sdk/runtime-reference.html">Widget Runtime Reference</a></strong></td><td>The lifecycle contract — see <a href="/docs/custom-widgets/v2/core-concepts.html">Widget Runtime</a> for how it works</td><td>Directly on <code>sdk</code>, for example <code>sdk.getContainer()</code> and <code>sdk.getProps()</code></td><td>Gives your widget its shadow root, current props, design tokens, and events</td></tr><tr><td><strong><a href="/docs/sdk/connectors-sdk/overview.html">Connectors SDK</a></strong></td><td>A backend proxy client, shared by every widget on the page</td><td><code>sdk.connectors</code></td><td>Call <a href="/docs/connectors/">Connectors</a> to reach external APIs without exposing credentials in the browser</td></tr><tr><td><strong><a href="/docs/sdk/web-sdk/overview.html">Web SDK</a></strong></td><td>The community-platform client</td><td><code>sdk.web</code> — <code>undefined</code> on host pages that publish no Web SDK</td><td>Search content, manage users and subscriptions, and interact with the DOM on community pages</td></tr></tbody></table><p>Nothing on <code>sdk</code> needs to be constructed or loaded: it already exists by the time your <code>init</code> function runs, the same way React hands a component its <code>props</code> or Express hands a handler <code>req</code>/<code>res</code>.</p><p><code>sdk.web</code> is <code>undefined</code> where the host page publishes no Web SDK — embedded widgets on non-community host pages, and Skilljar. Check it before use:</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sdk</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sdk.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">whenReady</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sdk.web) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // no Web SDK on this host page (e.g. embedded widgets, Skilljar)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="why-they-re-kept-separate" tabindex="-1">Why they&#39;re kept separate <a class="header-anchor" href="#why-they-re-kept-separate" aria-label="Permalink to &quot;Why they&#39;re kept separate&quot;">​</a></h2><p>Each layer talks to something different, so collapsing them would mix unrelated concerns:</p><ul><li><strong><code>sdk.connectors</code></strong> is a backend proxy client. Calling an external API directly from the browser would expose your credentials, so this client exists purely to route requests through the platform instead, keeping credentials on the server. It is one client shared by every widget on the page, so configuration changes made through it apply to all of them.</li><li><strong><code>sdk.web</code></strong> is a community-platform client. It has nothing to do with external APIs — it searches and manages content that already lives in the community itself.</li><li><strong>The runtime</strong> (the rest of <code>sdk</code>) isn&#39;t a client for anything external. It&#39;s the contract between the platform and your widget&#39;s lifecycle: where to render, what configuration you were given, and what to do when that configuration changes.</li></ul><p>A widget can use all three at once — read its props from the runtime, call a connector through <code>sdk.connectors</code>, and search community content through <code>sdk.web</code> — without any of the three needing to know the others exist.</p><h2 id="older-code-the-window-globals" tabindex="-1">Older code: the window globals <a class="header-anchor" href="#older-code-the-window-globals" aria-label="Permalink to &quot;Older code: the window globals&quot;">​</a></h2><p>Earlier widget code reached these through globals: <code>new window.WidgetServiceSDK()</code> for connectors and <code>window.ChWebSdk</code> for the Web SDK. Both are deprecated. They still work, but use <code>sdk.connectors</code> and <code>sdk.web</code> from <code>init(sdk)</code> instead.</p><p>The SDKs are available only through the <code>sdk</code> object your widget&#39;s <code>init(sdk)</code> receives. Script extensions and other page scripts have no SDK access — if you need community data or a connector, build a <a href="/docs/custom-widgets/v2/build-first-widget.html">widget</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><ul><li><a href="/docs/custom-widgets/v2/build-first-widget.html">Your First Widget</a> — build a widget hands-on and see the <code>init(sdk)</code> parameter in action</li><li><a href="/docs/sdk/connectors-sdk/overview.html">Connectors SDK</a> — call connectors with <code>sdk.connectors</code></li><li><a href="/docs/sdk/web-sdk/overview.html">Web SDK</a> — search, users, and subscriptions with <code>sdk.web</code></li><li><a href="/docs/sdk/runtime-reference.html">Widget Runtime Reference</a> — full API for the <code>init(sdk)</code> parameter</li></ul>`,17)])])}const g=t(o,[["render",i]]);export{k as __pageData,g as default};
